 "content": "from collections import Counter, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    # The sparse marks lie on a family of parallel diagonals. Choose the
    # orientation that groups them into the fewest occupied diagonals.
    groups = []
    for key_fn in (lambda r, c: r + c, lambda r, c: r - c):
        by_diag = defaultdict(set)
        for r, c, v in cells:
            by_diag[key_fn(r, c)].add(v)
        groups.append(by_diag)
    by_diag = min(groups, key=lambda d: (len(d), sum(len(vs) != 1 for vs in d.values())))
    colors = {k: next(iter(vs)) for k, vs in by_diag.items() if len(vs) == 1}
    n = len(colors)
    if not n:
        return [row[:] for row in grid]
    seq = [None] * n
    for diag, color in colors.items():
        seq[diag % n] = color
    # Fill the grid with the diagonal, one-cell-shifted repeating color cycle.
    return [[seq[(c - r) % n] for c in range(w)] for r in range(h)]
